#!/usr/bin/env python3
# patch_new_free_video_chat_article.py
# Replaces the content of post-free-video-chat-XX.html (12 languages) with the new CEO article.
# Updates: <title>, meta description, og:title/og:description, article:modified_time,
# JSON-LD (Article + FAQPage), the <main> body (text, 2 images, FAQ, CTA).
# Keeps: URL, canonical, hreflang, header, footer, related-posts block.
# Usage (from the project folder omegle-clone):
#   python patch_new_free_video_chat_article.py            (dry run - writes nothing)
#   python patch_new_free_video_chat_article.py --apply    (writes files)
import os, re, sys, json, glob, zlib, base64, html
APPLY = '--apply' in sys.argv
PUB = 'public' if os.path.isdir('public') else '.'
MODIFIED = '2026-10-27'
LANGS = ['ar','en','es','fr','de','it','pt','tr','ru','hi','id','zh']
DATA = ""
IMG1 = ('randly-home-screen.webp', 840, 1225, "")
IMG2 = ('randly-country-translation-v2.webp', 1200, 649, "")
ART = json.loads(zlib.decompress(base64.b64decode(DATA)).decode('utf-8'))

def esc(t): return html.escape(t, quote=False)
def esca(t): return html.escape(t, quote=True)
def plain(t):
    t = re.sub(r'\[([^\]]+)\]\((?:home|omegle|ome)\)', r'\1', t)
    return t.replace('**', '')

def exists(name): return os.path.exists(os.path.join(PUB, name))

def targets(lang):
    om = 'post-omegle-alternative-%s.html' % lang
    ome = 'post-randly-vs-ome-tv-%s.html' % lang
    if not exists(ome) and exists('post-randly-vs-ome-tv.html') and lang == 'en': ome = 'post-randly-vs-ome-tv.html'
    return {'home': 'https://randly.live/', 'omegle': om, 'ome': ome}

def inline(t, tg, warn):
    out = esc(t)
    def link(m):
        href = tg[m.group(2)]
        if m.group(2) != 'home' and not exists(href):
            warn.append('link target missing: ' + href + ' (written as plain text)')
            return m.group(1)
        return '<a href="%s" style="color: var(--accent-purple);">%s</a>' % (href, m.group(1))
    out = re.sub(r'\[([^\]]+)\]\((home|omegle|ome)\)', link, out)
    out = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', out)
    return out

def render(lang, d, side, align, warn):
    m, tg = d['meta'], targets(lang)
    P = lambda t: inline(t, tg, warn)
    o = []
    o.append('<p style="color: var(--text-muted); font-size: 0.85rem; margin-bottom: 8px;">%s</p>' % esc(m['updated']))
    o.append('<h1 style="font-size: 2rem; color: var(--accent-purple); margin-bottom: 20px; line-height: 1.4;">%s</h1>' % esc(m['h1']))
    blocks = d['blocks']; i = 0
    LI = '<li style="margin-bottom: 10px;">%s</li>'
    while i < len(blocks):
        b = blocks[i]; t = b['t']
        if t == 'p': o.append('<p>%s</p>' % P(b['x']))
        elif t == 'h2': o.append('<h2 style="margin-top: 36px; margin-bottom: 14px; font-size: 1.4rem;">%s</h2>' % esc(b['x']))
        elif t == 'h3': o.append('<h3 style="margin-top: 24px; margin-bottom: 10px; font-size: 1.15rem; color: var(--accent-purple);">%s</h3>' % esc(b['x']))
        elif t in ('ul', 'ol'):
            o.append('<%s style="padding-%s: 20px; margin-bottom: 16px;">' % (t, side))
            o += [LI % P(x) for x in b['items']]
            o.append('</%s>' % t)
        elif t == 'img':
            f, w, h, _ = IMG1 if b['n'] == 1 else IMG2
            alt = m['alt%d' % b['n']]
            mw = 'max-width: 420px; ' if b['n'] == 1 else ''
            o.append('<p style="text-align: center; margin: 22px 0;"><img src="/%s" alt="%s" width="%d" height="%d" loading="lazy" decoding="async" style="%swidth: 100%%; height: auto; border-radius: 14px;"></p>' % (f, esca(alt), w, h, mw))
        elif t == 'table':
            td = 'padding: 10px; border: 1px solid var(--border-color);'
            o.append('<div style="overflow-x: auto; margin-bottom: 20px;">')
            o.append('<table style="width: 100%; border-collapse: collapse; font-size: 0.9rem;">')
            o.append('<thead>\n<tr style="background: var(--bg-card);">')
            for k, h in enumerate(b['head']):
                o.append('<th style="padding: 10px; border: 1px solid var(--border-color); text-align: %s;">%s</th>' % (align if k == 0 else 'center', esc(h)))
            o.append('</tr>\n</thead>\n<tbody>')
            for r in b['rows']:
                o.append('<tr>' + ''.join('<td style="%s%s">%s</td>' % (td, '' if k == 0 else ' text-align: center;', esc(c)) for k, c in enumerate(r)) + '</tr>')
            o.append('</tbody>\n</table>\n</div>')
        elif t == 'faq':
            faqs = []
            while i < len(blocks) and blocks[i]['t'] == 'faq': faqs.append(blocks[i]); i += 1
            i -= 1
            for k, q in enumerate(faqs):
                mb = '30px' if k == len(faqs) - 1 and False else '16px'
                o.append('<div style="margin-bottom: %s;">\n<h3 style="font-size: 1.05rem; margin-bottom: 6px;">%s</h3>\n<p style="color: var(--text-muted);">%s</p>\n</div>' % (mb, esc(q['q']), esc(q['a'])))
        i += 1
    o.append('<div style="background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 12px; padding: 24px; text-align: center; margin-top: 30px;">\n<p style="font-size: 1.1rem; margin-bottom: 16px;">%s</p>\n<a href="https://randly.live/" style="display: inline-block; background: var(--accent-strong, #00805f); color: #fff; padding: 12px 28px; border-radius: 10px; text-decoration: none; font-weight: 700;">%s</a>\n</div>' % (esc(m['cta_text']), esc(m['cta_button'])))
    return '\n\n' + '\n\n'.join(o) + '\n\n'

def dump_ld(obj): return json.dumps(obj, ensure_ascii=False, indent=2)

def patch(lang, s, warn):
    d = ART[lang]; m = d['meta']
    # direction helpers detected from the existing page
    mm = re.search(r'<ul style="padding-(left|right): 20px', s)
    side = mm.group(1) if mm else ('right' if lang == 'ar' else 'left')
    mm = re.search(r'<th[^>]*text-align: (left|right)', s)
    align = mm.group(1) if mm else ('right' if lang == 'ar' else 'left')
    # <title>
    mt = re.search(r'<title>(.*?)</title>', s, re.S)
    if not mt: warn.append('no <title>'); return None
    suffix = ' | Randly' if mt.group(1).rstrip().endswith('| Randly') else ''
    s, n1 = re.subn(r'<title>.*?</title>', lambda _: '<title>%s%s</title>' % (esc(m['title']), suffix), s, count=1, flags=re.S)
    def meta(attr, name, val):
        nonlocal s
        pat = re.compile(r'(<meta %s="%s" content=")[^"]*(")' % (attr, re.escape(name)))
        s, n = pat.subn(lambda x: x.group(1) + esca(val) + x.group(2), s, count=1)
        if n != 1: warn.append('meta not found: ' + name)
    meta('name', 'description', m['description'])
    meta('property', 'og:title', m['title'])
    meta('property', 'og:description', m['description'])
    meta('property', 'article:modified_time', MODIFIED)
    # JSON-LD
    def ld(mo):
        try: obj = json.loads(mo.group(2))
        except Exception: warn.append('JSON-LD unreadable'); return mo.group(0)
        if obj.get('@type') == 'Article':
            obj['headline'] = m['headline']; obj['description'] = m['description']; obj['dateModified'] = MODIFIED
            obj['image'] = obj.get('image', 'https://randly.live/randly-logo-512.png')
        elif obj.get('@type') == 'FAQPage':
            obj['mainEntity'] = [{'@type': 'Question', 'name': plain(b['q']), 'acceptedAnswer': {'@type': 'Answer', 'text': plain(b['a'])}} for b in d['blocks'] if b['t'] == 'faq']
        else: return mo.group(0)
        return mo.group(1) + '\n' + dump_ld(obj) + '\n' + mo.group(3)
    s, nld = re.subn(r'(<script type="application/ld\+json">)(.*?)(</script>)', ld, s, flags=re.S)
    if nld != 2: warn.append('expected 2 JSON-LD blocks, found %d' % nld)
    # <main> body
    mm = re.search(r'(<main[^>]*>)(.*?)(</main>)', s, re.S)
    if not mm: warn.append('no <main>'); return None
    body = render(lang, d, side, align, warn)
    s = s[:mm.end(1)] + body + s[mm.start(3):]
    return s

def write_asset(spec):
    name, w, h, b64 = spec
    blob = base64.b64decode(b64); p = os.path.join(PUB, name)
    if os.path.exists(p) and open(p, 'rb').read() == blob: print('SAME    ', name); return
    print('WRITE   ' if APPLY else 'WOULD WRITE', name)
    if APPLY: open(p, 'wb').write(blob)

write_asset(IMG1); write_asset(IMG2)
ch = same = bad = 0
for lang in LANGS:
    fn = os.path.join(PUB, 'post-free-video-chat-%s.html' % lang)
    if not os.path.exists(fn): print('MISSING ', os.path.basename(fn)); bad += 1; continue
    raw = open(fn, 'rb').read(); crlf = b'\r\n' in raw
    s = raw.decode('utf-8').replace('\r\n', '\n')
    warn = []
    new = patch(lang, s, warn)
    for w in warn: print('  NOTE  ', lang, '-', w)
    if new is None: print('SKIP    ', os.path.basename(fn)); bad += 1; continue
    if new == s: print('SAME    ', os.path.basename(fn)); same += 1; continue
    print('CHANGE  ' if APPLY else 'WOULD CHANGE', os.path.basename(fn), '(%d chars)' % len(new)); ch += 1
    if APPLY:
        out = new.replace('\n', '\r\n') if crlf else new
        open(fn, 'wb').write(out.encode('utf-8'))
# sitemap lastmod (optional)
sm = os.path.join(PUB, 'sitemap.xml')
if os.path.exists(sm):
    x = open(sm, 'rb').read().decode('utf-8'); nx = x; cnt = 0
    for lang in LANGS:
        pat = re.compile(r'(<loc>https://randly\.live/post-free-video-chat-%s\.html</loc>\s*<lastmod>)[^<]*(</lastmod>)' % lang)
        nx, n = pat.subn(lambda m_: m_.group(1) + MODIFIED + m_.group(2), nx); cnt += n
    if nx != x:
        print('SITEMAP ', 'lastmod updated for %d urls' % cnt if APPLY else 'would update lastmod for %d urls' % cnt)
        if APPLY: open(sm, 'wb').write(nx.encode('utf-8'))
    else: print('SITEMAP  no change (%d matched)' % cnt)
print('changed: %d | unchanged: %d | problems: %d' % (ch, same, bad))
if not APPLY: print('Dry run only. Add --apply to write.')